CREATE OR REPLACE FUNCTION public.riser_scan_jobs(_asset_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=public.get_user_org_id(); a public.assets%ROWTYPE; result jsonb; BEGIN IF auth.uid() IS NULL OR o IS NULL OR NOT public.is_org_active(o) OR public.is_customer_user(auth.uid()) OR NOT (public.has_role_in_org(auth.uid(),o,'engineer') OR public.has_role_in_org(auth.uid(),o,'admin')) THEN RAISE EXCEPTION 'Staff access required'; END IF; SELECT * INTO a FROM public.assets WHERE id=_asset_id AND org_id=o AND asset_type IN ('Dry Riser','Wet Riser'); IF NOT FOUND THEN RAISE EXCEPTION 'Riser not available in your company'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('id',j.id,'reference',j.reference_number,'name',j.name,'date',j.due_date) ORDER BY j.created_at),'[]'::jsonb) INTO result FROM public.jobs j WHERE j.org_id=o AND j.site_id=a.site_id AND j.status IN ('active','scheduled','in_progress','requires_revisit','rejected') AND (NOT EXISTS(SELECT 1 FROM public.job_assignments ja WHERE ja.job_id=j.id AND ja.org_id=o) OR EXISTS(SELECT 1 FROM public.job_assignments ja WHERE ja.job_id=j.id AND ja.org_id=o AND ja.engineer_id=auth.uid())) AND (j.asset_id=a.id OR EXISTS(SELECT 1 FROM public.job_sheet_responses r WHERE r.job_id=j.id AND r.org_id=o AND r.archived_at IS NULL AND (r.responses->>'riser_asset_id'=a.id::text OR r.responses->'_riser_visit'->>'asset_id'=a.id::text))); RETURN result; END $$; REVOKE ALL ON FUNCTION public.riser_scan_jobs(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.riser_scan_jobs(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.start_riser_scan_service(_asset_id uuid,_job_id uuid DEFAULT NULL,_type text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o uuid:=public.get_user_org_id(); u uuid:=auth.uid(); today date:=(now() AT TIME ZONE 'Europe/London')::date; a public.assets%ROWTYPE; s public.sites%ROWTYPE; c public.customers%ROWTYPE; j public.jobs%ROWTYPE; r public.job_sheet_responses%ROWTYPE; t public.job_sheet_templates%ROWTYPE; candidates jsonb; typ text; cat text; ctx jsonb; answers jsonb; f jsonb; v text; loc text; created boolean:=false; BEGIN IF u IS NULL OR o IS NULL OR NOT public.is_org_active(o) OR public.is_customer_user(u) OR NOT (public.has_role_in_org(u,o,'engineer') OR public.has_role_in_org(u,o,'admin')) THEN RAISE EXCEPTION 'Staff access required'; END IF; SELECT * INTO a FROM public.assets WHERE id=_asset_id AND org_id=o AND asset_type IN ('Dry Riser','Wet Riser') AND status<>'decommissioned'; IF NOT FOUND OR a.site_id IS NULL THEN RAISE EXCEPTION 'Riser is not available at a site in your company'; END IF; SELECT * INTO s FROM public.sites WHERE id=a.site_id AND org_id=o AND deleted_at IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'Site not found'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(o::text||':'||s.id::text||':riser-scan:'||today::text,0)); candidates:=public.riser_scan_jobs(a.id); IF _job_id IS NOT NULL THEN IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(candidates) x WHERE x->>'id'=_job_id::text) THEN RAISE EXCEPTION 'This job is no longer available to you for this riser'; END IF; SELECT * INTO j FROM public.jobs WHERE id=_job_id AND org_id=o FOR UPDATE; ELSIF jsonb_array_length(candidates)>1 THEN RETURN jsonb_build_object('choices',candidates); ELSIF jsonb_array_length(candidates)=1 THEN SELECT * INTO j FROM public.jobs WHERE id=(candidates->0->>'id')::uuid AND org_id=o FOR UPDATE; ELSE SELECT * INTO j FROM public.jobs WHERE org_id=o AND site_id=s.id AND source='Riser QR' AND (created_at AT TIME ZONE 'Europe/London')::date=today AND status IN ('active','scheduled','in_progress') ORDER BY created_at,id LIMIT 1 FOR UPDATE; IF j.id IS NOT NULL AND EXISTS(SELECT 1 FROM public.job_assignments WHERE job_id=j.id AND org_id=o) AND NOT EXISTS(SELECT 1 FROM public.job_assignments WHERE job_id=j.id AND org_id=o AND engineer_id=u) THEN RAISE EXCEPTION 'Today’s scan visit is assigned to another engineer; ask the office to assign you'; END IF; END IF; IF j.id IS NOT NULL THEN SELECT * INTO r FROM public.job_sheet_responses WHERE job_id=j.id AND org_id=o AND archived_at IS NULL AND (responses->>'riser_asset_id'=a.id::text OR responses->'_riser_visit'->>'asset_id'=a.id::text) ORDER BY (status='submitted') DESC,created_at,id LIMIT 1 FOR UPDATE; END IF; IF r.id IS NULL THEN typ:=_type; IF typ IS NULL AND j.id IS NOT NULL THEN typ:=CASE WHEN j.category ~ '(pressure|annual)' THEN 'pressure' WHEN j.category ~ 'visual' THEN 'visual' ELSE NULL END; END IF; IF typ IS NULL THEN RETURN jsonb_build_object('needs_type',true,'job_id',j.id); END IF; IF typ NOT IN ('visual','pressure') THEN RAISE EXCEPTION 'Choose Visual inspection or Pressure test'; END IF; cat:=CASE WHEN a.asset_type='Dry Riser' THEN CASE WHEN typ='pressure' THEN 'dry_riser_pressure_test' ELSE 'dry_riser_visual' END ELSE CASE WHEN typ='visual' THEN 'wet_riser_visual' ELSE 'wet_riser_annual_service' END END; SELECT tt.* INTO t FROM public.job_sheet_templates tt LEFT JOIN public.job_category_template_map m ON m.template_id=tt.id AND m.job_category_slug=cat AND (m.org_id=o OR m.org_id IS NULL) WHERE tt.status='published' AND (tt.org_id=o OR tt.org_id IS NULL) AND (tt.job_category=cat OR m.id IS NOT NULL) AND lower(tt.name) NOT LIKE '%retired%' ORDER BY (tt.org_id=o) DESC,m.is_default DESC NULLS LAST,tt.updated_at DESC,tt.id LIMIT 1; IF t.id IS NULL THEN RAISE EXCEPTION 'No published % template is configured for this company. Ask the office to configure it.',typ; END IF; SELECT * INTO c FROM public.customers WHERE id=coalesce(j.customer_id,public.riser_visit_customer(s.id)) AND org_id=o; IF c.id IS NULL THEN RAISE EXCEPTION 'Link this site to a customer before starting service'; END IF; IF j.id IS NULL THEN INSERT INTO public.jobs(name,site_id,address,customer_id,customer,category,status,priority,source,created_by,org_id,due_date,visual_qty,pressure_test_qty) VALUES(s.name||' — '||a.asset_type||' service',s.id,s.address,c.id,c.name,cat,'in_progress','medium','Riser QR',u,o,today,CASE WHEN typ='visual' THEN 1 ELSE 0 END,CASE WHEN typ='pressure' THEN 1 ELSE 0 END) RETURNING * INTO j; created:=true; END IF; loc:=coalesce(nullif(a.riser_location,''),a.name,a.asset_tag); ctx:=jsonb_build_object('job_id',j.id,'asset_id',a.id,'asset_tag',a.asset_tag,'riser_name',a.name,'riser_location',loc,'outlets_count',a.outlets_count,'last_inspection_at',a.last_inspection_at,'last_inspection_type',a.last_inspection_type,'last_inspection_result',a.last_inspection_result,'customer',c.name,'site_name',s.name,'address',concat_ws(', ',s.address,s.postcode),'job_reference',j.reference_number,'planned_date',today,'visit_type',typ); answers:=jsonb_build_object('riser_asset_id',a.id,'riser_location',loc,'riser_name',a.name,'riser_id',a.asset_tag,'_riser_visit',ctx,'_system_label',loc); FOR f IN SELECT * FROM jsonb_array_elements(t.fields) LOOP v:=NULL; IF f->>'id'='riser_location' THEN v:=loc; ELSIF lower(f->>'label') LIKE '%outlet%' AND f->>'type'='number' THEN v:=a.outlets_count::text; ELSIF f->>'id'='customer_details' THEN v:=c.name; ELSIF f->>'id'='site_details' THEN v:=concat_ws(E'\n',s.name,s.address,s.postcode); ELSIF f->>'id'='date' THEN v:=today::text; ELSIF lower(f->>'label') ~ '(job ref|reference)' AND lower(f->>'label') !~ 'po' THEN v:=j.reference_number; END IF; IF v IS NOT NULL THEN answers:=answers||jsonb_build_object(f->>'id',v); END IF; END LOOP; answers:=answers||jsonb_build_object('_visit_prefill',answers-'_riser_visit'-'_system_label'); INSERT INTO public.job_sheet_responses(job_id,template_id,submitted_by,status,responses,system_label,org_id) VALUES(j.id,t.id,u,'draft',answers,loc,o) RETURNING * INTO r; END IF; INSERT INTO public.job_assignments(job_id,engineer_id,org_id) VALUES(j.id,u,o) ON CONFLICT(job_id,engineer_id) DO NOTHING; IF r.status='draft' AND r.submitted_by IS DISTINCT FROM u THEN IF r.submitted_by IS NOT NULL AND NOT public.has_role_in_org(r.submitted_by,o,'admin') THEN RAISE EXCEPTION 'This report has been started by another engineer'; END IF; UPDATE public.job_sheet_responses SET submitted_by=u WHERE id=r.id AND org_id=o; END IF; IF r.status='not_used' THEN UPDATE public.job_sheet_responses SET status='draft',submitted_by=u WHERE id=r.id AND org_id=o; END IF; UPDATE public.jobs SET status='in_progress' WHERE id=j.id AND org_id=o AND status IN ('active','scheduled','requires_revisit','rejected'); INSERT INTO public.job_activity_log(job_id,user_id,action,details,org_id) VALUES(j.id,u,'riser_qr_attendance',jsonb_build_object('asset_id',a.id,'asset_tag',a.asset_tag,'scanned_at',now(),'engineer_id',u,'attendance','on_site')::text,o); RETURN jsonb_build_object('job_id',j.id,'response_id',r.id,'template_id',r.template_id,'status',r.status,'created',created); END $$; REVOKE ALL ON FUNCTION public.start_riser_scan_service(uuid,uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.start_riser_scan_service(uuid,uuid,text) TO authenticated,service_role;